  'audioDrawer.note.currentOutput': "사용 중인 출력 경로를 보여줍니다. 공유는 매일 듣기 위한 것입니다. ASIO 및 WASAPI Exclusive는 금색으로 강조 표시됩니다.",
  'audioDrawer.note.dsdAutoVolumeLock': "기본적으로 꺼져 있습니다. 활성화되면 DSD 재생 중에 ECHO 볼륨이 일시적으로 100%로 잠기고 재생이 PCM으로 돌아오면 복원됩니다.",
  'audioDrawer.note.dsdDop': '기본적으로 켜져 있습니다. 조건에 맞는 로컬 DSF는 ASIO 또는 WASAPI Exclusive에서 DoP를 사용하고 호환되지 않으면 PCM으로 돌아갑니다. ASIO Native DSD는 별도의 선택형 실험 기능입니다. 최종 확인은 DAC 표시를 보세요.',
  'audioDrawer.note.engine': "출력 장치, 모드, 샘플링 속도, EQ, 리샘플링 상태를 빠르게 확인하세요.",
  'audioDrawer.note.miniaudioOutput': "실험적이며 기본적으로 꺼져 있습니다. 이 스위치는 Windows WASAPI 공유용 PCM 출력에만 영향을 미칩니다. 미니 오디오를 통해 WASAPI Exclusive, ASIO, DoP 또는 기본 DSD를 라우팅하지 않습니다.",
  'audioDrawer.note.releaseExclusiveOnPause': '실험적입니다. 일시정지하면 WASAPI Exclusive를 풀어 다른 앱이 소리를 낼 수 있습니다. 재개 시 Exclusive를 다시 시도하고, 필요하면 잠시 Shared로 돌아갑니다.',
  'audioDrawer.option.active': '켜짐',
  'audioDrawer.option.alsaShared': "알사",
  'audioDrawer.option.alsaSharedDescription': "Linux ALSA 장치를 통해 출력됩니다.",
  'audioDrawer.option.asioNativeDsd': "ASIO 네이티브 DSD 실험",
  'audioDrawer.option.automaticOutput': "자동 출력(권장)",
  'audioDrawer.option.automaticOutputDescription': '기본적으로 꺼져 있습니다. 켜면 오디오 엔진이 시스템 기본 장치를 따르고, Shared 출력과 안전한 복구를 사용합니다. 켜져 있는 동안 수동 장치와 Exclusive 설정은 잠깁니다.',
  'audioDrawer.option.automaticOutputStage.directSound': "WASAPI를 시작할 수 없어 DirectSound 호환 모드를 통해 자동 출력이 복구되었습니다.",
  'audioDrawer.option.automaticOutputStage.failed': "기본 엔진 오류를 숨기지 않기 위해 자동 복구가 중지되었습니다. 오디오 진단을 확인하세요.",
  'audioDrawer.option.automaticOutputStage.safeShared': "WASAPI는 안정적인 버퍼로 이동되었으며 여전히 시스템 기본 장치를 사용하고 있습니다.",
  'audioDrawer.option.automaticOutputStage.systemRequired': "기본 호환성 출력도 실패했습니다. 시스템 오디오 안전 모드로 전환합니다.",
  'audioDrawer.option.automix': "스마트 전환 활성화",
  'audioDrawer.option.automixActive': "현재 재생은 Smart Transition 듀얼 데크 경로를 사용하고 있습니다.",
  'audioDrawer.option.automixDescription': "베타이며 기본적으로 꺼져 있습니다. 활성화되면 지원되지 않는 경우에 대한 안전한 대체와 함께 템포, 키, 프레이즈 및 에너지 분석을 사용하여 다음 트랙으로 전환됩니다.",
  'audioDrawer.option.directSound': "DirectSound 호환성",
  'audioDrawer.option.directSoundDescription': "대기 시간이 긴 수동 호환성 모드; WASAPI 재생이 실패한 경우에만 시도하십시오.",
  'audioDrawer.option.dsdAutoVolumeLock': "DSD 재생 중 볼륨 자동 잠금",
  'audioDrawer.option.dsdDop': "DSD 패스스루(DoP)",
  'audioDrawer.option.fixedVolume': "고정 볼륨",
  'audioDrawer.option.fixedVolumeDescription': "활성화되면 ECHO 볼륨 제어가 100%로 잠깁니다. ReplayGain은 여전히 ​​독립적으로 적용됩니다.",
  'audioDrawer.option.linuxAutoShared': '자동',
  'audioDrawer.option.linuxAutoSharedDescription': "ALSA를 선호하고 시스템 PipeWire/ALSA 호환성 계층을 존중합니다.",
  'audioDrawer.option.lowLoadPlaybackEnhancements': "향상된 저부하 보호",
  'audioDrawer.option.lowLoadPlaybackEnhancementsDescription': "기본적으로 꺼져 있습니다. 저부하 재생 모드가 활성화된 경우에만 적용되며 폴링, 데스크톱 가사, 진단, 백그라운드 라이브러리 작업, 스트리밍 사전 준비 및 자동 MV 검색이 더욱 줄어듭니다.",
  'audioDrawer.option.lowLoadPlaybackMode': "저부하 재생 모드",
  'audioDrawer.option.lowLoadPlaybackModeDescription': "실시간 스펙트럼, 빈번한 재생 페이지 새로 고침, ReplayGain/BPM 재분석, 고주파 단어 가사 업데이트, 자동 심층 가사 검색, 표지/아티스트 이미지 가져오기 및 재생 중 MV 사전 로드를 비활성화합니다.",
  'audioDrawer.option.miniaudioOutput': "miniaudio WASAPI 출력 실험",
  'audioDrawer.option.nativeDirectLocalPlayback': "로컬 직접 재생 실험",
  'audioDrawer.option.releaseExclusiveOnPause': '일시정지 시 Exclusive 해제',
  'audioDrawer.option.rememberOutput': "출력 설정 저장",
  'audioDrawer.option.rememberOutputDescription': "다음 실행 시 선택한 출력 장치, 출력 모드, 버퍼 및 관련 설정을 복원합니다.",
  'audioDrawer.option.set': "설정",
  'audioDrawer.option.sharedBackend': "공유 백엔드",
  'audioDrawer.option.showAsioPanelSettings': "ASIO 패널 설정 표시",
  'audioDrawer.option.showAsioPanelSettingsDescription': "기본적으로 꺼져 있습니다. 활성화되면 ASIO 장치에 ASIO 패널 열기 버튼이 표시됩니다.",
  'audioDrawer.option.wasapiExclusive': "WASAPI 독점 모드",
  'audioDrawer.option.wasapiExclusiveDescription': "공유는 일상적인 Windows 경로입니다. Exclusive는 공유 믹서 없이 동일한 장치를 열며 DAC 또는 오디오 인터페이스 및 드라이버가 안정적인 것으로 알려진 경우에만 권장됩니다. 온보드 Realtek 스타일 드라이버는 취약할 수 있으며 침묵, 끊김 또는 스위치 오류를 일으킬 수 있습니다.",
