  'audioDrawer.todo.outputControls': "목표 샘플 속도 및 버퍼 제어",
  'audioDrawer.todo.outputControlsDescription': "이 컨트롤은 현재 오디오 엔진에 연결됩니다. 실패한 스위치는 이전 출력을 유지하고 진단을 표시합니다.",
  'audioDrawer.troubleshooting.description': "오디오가 멈췄거나 장치 목록이 잘못된 경우 이 기능을 사용하세요. 소프트 재시작은 ECHO에만 영향을 미칩니다.",
  'audioDrawer.troubleshooting.hardAction': "Windows 오디오 서비스를 다시 시작",
  'audioDrawer.troubleshooting.hardBusy': "Windows 오디오 서비스를 다시 시작하는 중",
  'audioDrawer.troubleshooting.hardConfirm': "이렇게 하면 모든 앱(Chrome, 게임, 통화)의 오디오가 중단되며 관리자 권한이 필요합니다. 계속하다?",
  'audioDrawer.troubleshooting.hardDone': "Windows 오디오 서비스가 복구되었습니다. 재생을 다시 시작할 수 있습니다.",
  'audioDrawer.troubleshooting.softAction': "오디오 엔진 다시 시작",
  'audioDrawer.troubleshooting.softBusy': "오디오 엔진 다시 시작 중",
  'audioDrawer.troubleshooting.softDone': "오디오 엔진이 다시 시작되었습니다. 재생을 다시 시작할 수 있습니다.",
  'audioDrawer.troubleshooting.title': "오디오 문제 해결",
  'audioDrawer.warning.highOutputSampleRate': "현재 오디오 장치 샘플링 속도가 너무 높아 재생 속도 문제가 발생할 수 있습니다. 48kHz를 권장합니다.",
  'audioError.corruptFile': "이 오디오 파일은 손상되었거나 불완전할 수 있습니다. ECHO가 재생을 중단했습니다. 파일을 다시 획득하고 다시 가져옵니다.",
  'audioError.decodeFailed': "지금은 이 트랙을 디코딩하지 못했습니다. 재생을 다시 시도하십시오. 이 트랙에서만 실패하는 경우 파일 무결성을 확인하거나 다시 가져오십시오.",
  'audioError.deviceInitFailed': "오디오 장치 초기화에 실패했습니다. 출력 장치가 아직 온라인 상태인지 확인하세요. DAC를 연결한 후 오디오 엔진을 다시 시작하거나 샘플링 속도/버퍼 설정을 낮추세요.",
  'audioError.deviceNotFound': "선택한 오디오 장치가 없거나 연결이 끊겼습니다. ECHO가 시스템 기본 출력으로 대체를 시도했습니다.",
  'audioError.deviceTimeout': "오디오 장치의 반응이 너무 느립니다. USB DAC 또는 드라이버가 멈췄을 수 있습니다. USB를 다시 연결하거나 설정에서 오디오 엔진을 다시 시작하세요.",
  'audioError.exclusiveFailed': "WASAPI 단독 출력에 실패했습니다. 기기가 현재 형식을 지원하지 않거나 다른 앱에서 해당 형식을 사용 중일 수 있습니다. WASAPI 공유로 다시 전환하고 다시 시도하세요.",
  'audioError.generic': "재생에 실패했습니다. ECHO는 상세한 진단을 유지했습니다. 재생을 다시 시도하거나 설정 > 재생에서 일시적으로 호환 가능한 출력으로 전환하세요.",
  'audioError.hostAccessViolation': "Windows 출력을 시작하는 동안 오디오 엔진이 충돌했습니다. 오디오 엔진 또는 Windows 오디오 서비스를 다시 시작하십시오. 문제가 계속 발생하면 임시로 DirectSound 호환 출력으로 전환하세요.",
  'audioError.hostExitFailed': "오디오 출력 장치를 시작하지 못했습니다. 현재 출력 모드, 샘플링 속도 또는 버퍼 설정이 거부되었을 수 있습니다.",
  'audioError.hostInvalidExe': "오디오 엔진을 시작할 수 없습니다. 프로그램 파일이 유효한 Windows 실행 파일이 아닙니다. 다시 설치하거나 다시 빌드하고 echo-audio-host.exe / ffmpeg.exe가 손상되거나 교체되지 않았는지 확인하세요.",
  'audioError.hostReadyTimeout': "오디오 출력 시작 시간이 초과되었습니다. 드라이버가 느리거나 장치가 사용 중이거나 샘플링 속도/버퍼 설정이 거부되었을 수 있습니다.",
  'audioError.hostSpawnFailed': "오디오 엔진을 시작할 수 없습니다. 기본 호스트가 존재하고 보안 소프트웨어에 의해 차단되지 않는지 확인하세요.",
  'audioError.seekUnsupported': "현재로서는 이 위치를 찾는 데 실패했습니다. 파일 또는 네트워크 소스가 스크러빙을 지원하지 않을 수 있습니다.",
  'audioError.systemPlaybackFailed': "시스템 플레이어가 이 트랙을 재생할 수 없습니다. 한 번 다시 시도하거나 호환 가능한 출력으로 전환하고 다시 시도하십시오.",
  'audioProfessional.action.hideDetails': "전문적인 세부정보 숨기기",
