  'settings.danger.database.confirmWord': "위험 확인 문구",
  'settings.danger.database.description.healthy': "검사가 정상입니다. 여기서 스냅샷을 만들고, 손상되면 여기서 복구합니다.",
  'settings.danger.database.description.loading': "상태와 스냅샷을 읽는 중입니다.",
  'settings.danger.database.description.quarantined': "내장된 태그가 손상되었거나 텍스트가 너무 커서 라이브러리이 격리되었습니다. ECHO가 먼저 복구 흐름을 열고 음악 파일은 삭제되지 않습니다.",
  'settings.danger.database.description.recoverable': "데이터베이스를 사용할 수 없으면 ECHO는 먼저 정상 스냅샷에서 복원을 시도합니다. 현재 데이터베이스는 복구 전 보관되며, 음악 파일은 삭제되지 않습니다.",
  'settings.danger.database.description.unrecoverable': "정상 스냅샷에서는 데이터베이스를 복원할 수 없습니다. 음악파일은 삭제되지 않습니다. 진단을 내보내고 보호 폴더를 먼저 검사한 다음 잘못된 데이터베이스 보관 및 빈 라이브러리 재구축을 확인합니다.",
  'settings.danger.database.error.bridgeCreateSnapshot': "ECHO 데스크톱 앱이 필요합니다. ECHO 데스크톱 앱에서 정상 스냅샷을 생성하세요.",
  'settings.danger.database.error.bridgeDiscard': "데스크톱 브리지를 사용할 수 없음: ECHO 데스크톱 앱에 문제 트랙을 보관합니다.",
  'settings.danger.database.error.bridgeOpenProtection': "ECHO 데스크톱 앱이 필요합니다. ECHO 데스크톱 앱에서 보호 폴더를 엽니다.",
  'settings.danger.database.error.bridgeRebuild': "데스크톱 브리지를 사용할 수 없음: ECHO 데스크톱 앱에서 라이브러리 데이터베이스를 다시 구축하세요.",
  'settings.danger.database.error.bridgeRelaunch': "데스크톱 브리지를 사용할 수 없음: ECHO 데스크톱 앱에서 복구 모드로 다시 시작하세요.",
