  'settings.danger.database.steps.quarantined.1': "현재 라이브러리는 활성 위치 밖으로 이동되었으며 ECHO는 이러한 위험한 태그를 계속 읽지 않습니다.",
  'settings.danger.database.steps.quarantined.2': "먼저 \"격리된 복사본 복구\"를 선호하세요. 보관된 복사본에만 영향을 미치고 유효성 검사를 통과한 후에만 복원합니다.",
  'settings.danger.database.steps.quarantined.3': "복구가 실패하면 정상 스냅샷을 복원하거나 잘못된 데이터베이스를 보관하고 빈 라이브러리를 다시 빌드하도록 선택합니다. 음악파일은 삭제되지 않습니다.",
  'settings.danger.database.steps.recoverable.1': "먼저 라이브러리 스캔이 실행되고 있지 않은지 확인하십시오. 검색 중에는 복구, 재구축 및 삭제 작업이 거부됩니다.",
