  'settings.danger.database.steps.recoverable.3': "정상 스냅샷이 존재하지 않거나 복구로 인해 여전히 손상이 남아 있는 경우 \"잘못된 데이터베이스 보관 및 빈 라이브러리 재구축\"을 사용하십시오.",
  'settings.danger.database.steps.unrecoverable.1': "먼저 라이브러리 스캔이 실행되고 있지 않은지 확인하십시오. 검색 중에는 복구, 재구축 및 삭제 작업이 거부됩니다.",
  'settings.danger.database.steps.unrecoverable.2': "진단을 내보내고 먼저 보호 폴더를 열어 잘못된 데이터베이스 아카이브 추적이 보존되도록 하세요.",
  'settings.danger.database.steps.unrecoverable.3': "\"빈 라이브러리 재구축\"이라는 확인 문구를 입력한 후 잘못된 데이터베이스를 보관하고 빈 라이브러리를 재구축한 다음 라이브러리 폴더를 다시 추가하고 다시 스캔하세요.",
