  'settings.danger.database.unavailable.scrub': "복구 가능한 격리된 사본이 발견되지 않았습니다. 보호 폴더를 열어 아카이브가 있는지 확인하거나 진단을 직접 내보냅니다.",
  'settings.danger.deleteAll.action': "첫 번째 실행 상태 복원",
  'settings.danger.deleteAll.confirm': "ECHO를 첫 실행 상태로 복원하시겠습니까? 이렇게 하면 ECHO userData 및 외부 커버 캐시 디렉터리가 지워지고 앱이 자동으로 다시 시작됩니다. 음악 폴더 및 다운로드 출력 디렉터리는 적극적으로 삭제되지 않습니다.",
  'settings.danger.deleteAll.confirmMessage': "이렇게 하면 ECHO 설정, 계정, 플러그인, 라이브러리 데이터베이스, 재생 기록, 캐시, 로그, 배경화면 및 보호 스냅샷이 삭제된 다음 첫 실행 상태로 다시 시작됩니다. 음악파일은 삭제되지 않습니다.",
  'settings.danger.deleteAll.confirmWord': "모든 콘텐츠 삭제",
  'settings.danger.deleteAll.description': "설정, 계정, 플러그인, 라이브러리 데이터베이스, 캐시, 로그, 배경화면, 보호 스냅샷과 다운로드 작업 기록을 지운 뒤 ECHO를 자동으로 다시 시작합니다.",
  'settings.danger.deleteAll.message.deleted': "ECHO 로컬 콘텐츠가 삭제되었습니다. {removed} 경로가 삭제되었습니다.{failedText} ECHO가 첫 실행 상태로 다시 시작됩니다.",
  'settings.danger.deleteAll.message.failed': "{failed} 경로를 삭제하지 못했습니다. ECHO를 닫고 수동으로 검사하세요.",
  'settings.danger.deleteAll.message.notRestarted': "ECHO 로컬 콘텐츠가 완전히 지워지지 않았습니다. {removed} 경로가 삭제되었지만 {failed} 경로는 여전히 실패합니다. ECHO를 닫고 수동으로 검사하세요. 앱이 자동으로 다시 시작되지 않습니다.",
  'settings.danger.deleteAll.title': "첫 번째 실행 상태 복원",
  'settings.danger.deleteDatabase.action': "라이브러리 데이터베이스 삭제",
  'settings.danger.deleteDatabase.confirm': "라이브러리 데이터베이스를 삭제하시겠습니까? 이는 현재 데이터베이스 파일을 보관 및 삭제하고, 데이터베이스를 재구축하지 않으며, 음악 파일을 삭제하지 않습니다. 나중에 ECHO를 다시 시작한 다음 노래 폴더를 다시 추가하고 다시 검색하세요.",
  'settings.danger.deleteDatabase.confirmMessage': "아카이브를 삭제하고 현재 데이터베이스 파일을 제거합니다. 음악파일은 삭제되지 않습니다.",
  'settings.danger.deleteDatabase.confirmWord': "라이브러리 삭제",
