  'settings.danger.hardwareAcceleration.confirmDisable': "하드웨어 가속을 비활성화하시겠습니까? 다음 출시 시 Chromium은 소프트웨어 렌더링을 사용합니다. 애니메이션과 비디오는 속도가 느려질 수 있지만 이는 GPU 또는 이미지 메모리 부족을 진단하는 데 도움이 됩니다.",
  'settings.danger.hardwareAcceleration.confirmEnable': "하드웨어 가속을 복원하시겠습니까? 이는 ECHO를 완전히 다시 시작한 후에 적용됩니다.",
  'settings.danger.hardwareAcceleration.description': "이를 사용하여 비정상적인 Chromium, GPU 또는 이미지 캐시 메모리를 진단합니다. ECHO를 완전히 다시 시작한 후에 변경 사항이 적용됩니다.",
  'settings.danger.hardwareAcceleration.message.disabled': "ECHO를 완전히 종료하고 다시 시작하면 하드웨어 가속이 비활성화됩니다. 다시 시작한 후 메모리 문제를 재현합니다.",
