  'settings.danger.repair.confirm': "라이브러리 데이터베이스를 다시 구축하시겠습니까? 이는 현재 라이브러리 데이터베이스를 보관하고 음악 파일을 삭제하지 않고 활성 데이터베이스 색인을 삭제합니다. 재구축 후 노래 폴더를 다시 추가하고 다시 검색하세요.",
