  'settings.danger.repair.description': "라이브러리 데이터베이스가 완전히 손상되었거나 폴더를 다시 추가해도 작동하지 않거나 다시 검색해도 아무 작업도 수행되지 않는 경우 사용하십시오. 이전 데이터베이스를 보관하고 음악 파일을 삭제하지 않고 현재 색인을 삭제합니다.",
