  'settings.performance.description': "여기에서 저부하 재생, 앨범월 가상화 및 로컬 직접 재생을 관리하세요. 앨범월 가상화는 기본적으로 켜지고 나머지 두 항목은 꺼집니다. 확실하지 않으면 기본값을 유지하세요. 로컬 직접 재생을 적용할 수 없는 경우 표준 경로로 돌아갑니다.",
