  'settings.playback.asioNativeDsd.description': "기본적으로 꺼져 있습니다. EQ, 볼륨, 속도 및 DSP가 비활성화된 경우에만 ASIO + 로컬 DSF + DoP를 시도합니다. 오류는 기존 DoP/PCM 경로로 대체됩니다.",
