  'settings.playback.audioDrawerNotice.description': "이 섹션은 오른쪽 상단에 있는 오디오 서랍의 실시간 상태를 따릅니다. 두 표면이 잠시 불일치하는 경우 오른쪽 상단 서랍을 신뢰하십시오.",
  'settings.playback.audioDrawerNotice.status': "출력 모드, 공유 백엔드 및 장치를 조정하려면 오른쪽 상단 오디오 설정 창을 사용하세요.",
