  'settings.playback.audioStatus.description': "샘플링 속도 필드는 이전 ECHO 독점 모드 48k 잠금 회귀를 방지하기 위해 분리된 상태로 유지됩니다.",
  'settings.playback.audioStatus.title': "오디오 상태",
  'settings.playback.automaticOutput.description': "기본적으로 꺼져 있습니다. 모니터 스피커, Bluetooth 헤드폰 및 일상적인 오디오 장치용으로 설계되었습니다. 공유 출력, 균형 잡힌 대기 시간 및 안전한 대체 기능을 갖춘 시스템 기본 장치를 따릅니다. 수동 출력 제어는 활성화된 동안 잠깁니다.",
  'settings.playback.automaticOutput.recommended': "오디오 설정에 익숙하지 않은 사용자에게 권장됩니다.",
  'settings.playback.automaticOutput.statusDisabled': "자동 출력이 비활성화됩니다. 출력 모드와 장치는 수동으로 선택할 수 있습니다.",
  'settings.playback.automaticOutput.statusEnabled': "자동 출력이 활성화되고 시스템 기본 공유 경로를 사용합니다.",
  'settings.playback.automaticOutput.title': "자동 출력 적응",
  'settings.playback.automix.description': '현재 곡이 끝나기 전에 다음 곡을 준비하고 부드럽게 믹스해 연결합니다. 연속 감상에 적합하며 기본값은 꺼짐입니다.',
  'settings.playback.automix.title': "스마트 전환",
  'settings.playback.dsdDop.description': '기본적으로 켜져 있으며 조건에 맞는 로컬 DSF에만 씁니다. ASIO와 WASAPI Exclusive는 DoP를 사용하고 호환되지 않으면 PCM으로 돌아갑니다. ASIO Native DSD는 별도의 선택형 실험 기능입니다. 패스스루는 리샘플링하지 않습니다. 최종 확인은 DAC 표시를 보세요.',
