  'streaming.tabs.aria': "결과 유형",
  'streamingConsentNotice.acceptance': "계속한다는 것은 이 기능이 개인 로컬 클라이언트 도우미임을 이해하고 동의한다는 것을 의미합니다. 이는 법적 조언, 저작권 라이센스, 플랫폼 에이전시 관계 또는 모든 콘텐츠를 사용할 수 있다는 약속이 아닙니다.",
  'streamingConsentNotice.authorizedUse': "귀하는 액세스 권한이 있는 계정, 구독 및 콘텐츠만 사용해야 합니다. 플랫폼 약관, 다운로드 제한, DRM, 계정 위험 통제, 페이월 또는 저작권 보호를 우회하기 위해 이 기능을 사용하지 마십시오.",
  'streamingConsentNotice.bodyIntro': "ECHO 스트리밍 항목은 검색, 계정 상태, 즐겨찾기, 재생 목록 가져오기 및 재생 진입점만 통합합니다. ECHO는 제3자 스트리밍 플랫폼의 오디오, 비디오, 아트워크, 가사 또는 메타데이터에 대한 저작권을 소유, 호스팅, 판매 또는 재배포하지 않습니다.",
  'streamingConsentNotice.cancel': '취소',
  'streamingConsentNotice.close': "공지 닫기",
  'streamingConsentNotice.confirm': "동의하고 계속합니다",
  'streamingConsentNotice.consentPhrase': "동의해요",
  'streamingConsentNotice.disclaimer': "면책조항: ECHO는 계정 제한, 서비스 중단, 저작권 분쟁, DMCA 통지, 데이터 손실, 지역적 가용성 또는 제3자 플랫폼 사용으로 인해 발생하는 기타 손실에 대해 책임을 지지 않습니다.",
  'streamingConsentNotice.dmca': "DMCA는 미국 저작권법에 따른 통지 및 게시 중단 메커니즘입니다. 권리 보유자가 콘텐츠, 링크 또는 데이터 사용이 자신의 권리를 침해한다고 생각하는 경우 관련 플랫폼이나 합법적인 채널을 통해 통지를 제출해야 합니다. 또한 사용자는 권리 보유자 통지나 플랫폼 요청을 받은 경우 관련 사용을 중단해야 합니다.",
  'streamingConsentNotice.inputLabel': "계속하려면 \"{phrase}\"을 입력하세요",
  'streamingConsentNotice.license': "ECHO 코드와 플러그인은 프로젝트 라이선스의 적용을 받습니다. 크래킹, 승인 우회, 권한 위조, 무결성 검사 제거 또는 ECHO를 유료 콘텐츠에 대한 무단 액세스 도구로 사용하는 것은 금지됩니다.",
  'streamingConsentNotice.localFirst': "ECHO는 기본적으로 로컬 음악 플레이어이며 스트리밍은 제품 우선순위가 가장 낮습니다. 특정 플랫폼이나 오디오 소스 추가 요청은 거부됩니다. 스트리밍에 문제가 있는 경우 먼저 로컬 음악 라이브러리를 사용하십시오.",
  'streamingConsentNotice.noBypass': "ECHO는 멤버십 우회, 미리보기 크래킹, 결제 회피 또는 플랫폼이나 권리 소유자의 이익에 해를 끼치는 모든 플랫폼을 제공하지 않습니다. 노래가 30초 동안만 재생되는 경우 플랫폼 멤버십, 구독, 지역 및 계정 상태를 확인하세요.",
  'streamingConsentNotice.platformControl': "타사 플랫폼, 상표, 카탈로그, API, 계정, 구독, 쿠키, DRM, 지역 제한 및 재생 승인은 관련 플랫폼 및 권리 소유자에 의해 제어됩니다. ECHO는 해당 플랫폼을 대표하지 않으며 플랫폼 콘텐츠에 대한 라이선스를 부여하지 않습니다.",
  'streamingConsentNotice.title': "스트리밍 기능 공지",
  'streamingConsentNotice.uninstall': "스트리밍 플랫폼 멤버십이 너무 비싸다고 생각되면 이 기능 사용을 중단하고 소프트웨어를 제거하세요. 멤버십 크랙, 승인 우회, 저작권 보호 회피 또는 기타 불법 행위 수행 요청은 거부됩니다.",
